(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.02-t*0.28)*16 + Math.sin(x*0.016+t*0.38)*11;
  const w2x = Math.sin((x+w1x)*0.025-t*0.15)*8 + Math.cos((y+w1y)*0.02+t*0.18)*6;
  const w2y = Math.cos((y+w1y)*0.022+t*0.2)*7 + Math.sin((x+w1x)*0.019-t*0.16)*5;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.075, 2.1, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.095, 1.8, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.055, 2.4, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.11, 1.6, 0.85],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.065, 2.7, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.085, 2.0, 0.95],
    [80+Math.sin(t*0.45+1.5)*110, 120+Math.cos(t*0.65+2.5)*70, 0.1, 1.9, 0.8],
    [400+Math.cos(t*0.55+3)*85, 180+Math.sin(t*0.75+1)*65, 0.07, 2.5, 1.15],
    [200+Math.sin(t*0.25+4)*130, 40+Math.cos(t*0.45+3)*90, 0.08, 2.2, 0.9],
    [300+Math.cos(t*0.42+2)*95, 220+Math.sin(t*0.58+0.5)*55, 0.092, 1.75, 1.0]
  ];
  let aS=0, iS=0, cS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const decay=Math.exp(-d*0.003);
    aS+=Math.sin(d*f-t*sp)*w*decay;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w*decay;
    cS+=Math.sin(d*f*1.3-t*sp*0.4+3.0)*w*decay*0.5;
  }
  const n=10, act=aS/n, inh=iS/n, cor=cS/n;
  const bg=(Math.sin(sx*0.038+sy*0.024+t*0.85)+Math.sin(sx*0.028-sy*0.038+t*1.15))/2
    +Math.sin((sx+sy)*0.11+t*2.6)*0.18+Math.sin((sx-sy)*0.095-t*2.1)*0.18
    +Math.sin(sx*0.06*sy*0.0001+t*0.5)*0.1;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.048-ang*3.5-t*1.6)+Math.sin(dist*0.038+ang*4.5-t*1.3))*0.35
    +Math.sin(dist*0.08-ang*2-t*2.5)*0.15;
  const laplacian=Math.sin(sx*0.12)*Math.sin(sy*0.12)+Math.sin(sx*0.08+t)*Math.cos(sy*0.1-t*0.7);
  const reaction=Math.tanh((act-inh*0.65+cor*0.25+bg*0.28+spiral+laplacian*0.15)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.09+t)*0.5+Math.sin((sx-sy)*0.07-t*0.8)*0.3)*1.4)*0.28;
  const weave=Math.sin(sx*0.06+sy*0.04+t*0.3)*Math.cos(sx*0.035-sy*0.055-t*0.4)*0.15;
  const blend=reaction*0.6+cell*0.2+weave*0.2, v=blend*0.5+0.5;
  const pal=[
    [6,12,52],[12,42,88],[18,78,118],[24,128,142],
    [60,168,148],[140,195,120],[210,195,75],
    [225,155,60],[210,105,70],[175,58,72],
    [120,32,62],[60,18,48],[6,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge=Math.abs(reaction)>0.65?1.12+Math.abs(reaction)*0.08:1.0;
  const shimmer=Math.sin(t*3+sx*0.1+sy*0.08)*0.04*Math.max(0,reaction);
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*(lum+shimmer)*edge)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*(lum+shimmer)*edge)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*(lum+shimmer)*edge)|0
  ];
}
